INSERT INTO repo_sdg_targets (sdg_target_id, target_code, text, status) VALUES ('SDG_TARGET_12_1', '12.1', 'Implement the 10-Year Framework of Programmes on Sustainable Consumption and Production Patterns, all countries taking action, with developed countries taking the lead, taking into account the development and capabilities of developing countries', 'Active'), ('SDG_TARGET_12_2', '12.2', 'By 2030, achieve the sustainable management and efficient use of natural resources', 'Active'), ('SDG_TARGET_12_3', '12.3', 'By 2030, halve per capita global food waste at the retail and consumer levels and reduce food losses along production and supply chains, including post-harvest losses', 'Active'), ('SDG_TARGET_12_4', '12.4', 'By 2020, achieve the environmentally sound management of chemicals and all wastes throughout their life cycle, in accordance with agreed international frameworks, and significantly reduce their release to air, water and soil in order to minimize their adverse impacts on human health and the environment', 'Active'), ('SDG_TARGET_12_5', '12.5', 'By 2030, substantially reduce waste generation through prevention, reduction, recycling and reuse', 'Active'), ('SDG_TARGET_12_6', '12.6', 'Encourage companies, especially large and transnational companies, to adopt sustainable practices and to integrate sustainability information into their reporting cycle', 'Active'), ('SDG_TARGET_12_7', '12.7', 'Promote public procurement practices that are sustainable, in accordance with national policies and priorities', 'Active'), ('SDG_TARGET_12_8', '12.8', 'By 2030, ensure that people everywhere have the relevant information and awareness for sustainable development and lifestyles in harmony with nature', 'Active'), ('SDG_TARGET_12_a', '12.a', 'Support developing countries to strengthen their scientific and technological capacity to move towards more sustainable patterns of consumption and production', 'Active'), ('SDG_TARGET_12_b', '12.b', 'Develop and implement tools to monitor sustainable development impacts for sustainable tourism that creates jobs and promotes local culture and products', 'Active'), ('SDG_TARGET_12_c', '12.c', 'Rationalize inefficient fossil-fuel subsidies that encourage wasteful consumption by removing market distortions, in accordance with national circumstances, including by restructuring taxation and phasing out those harmful subsidies, where they exist, to reflect their environmental impacts, taking fully into account the specific needs and conditions of developing countries and minimizing the possible adverse impacts on their development in a manner that protects the poor and the affected communities', 'Active'), ('SDG_TARGET_13_1', '13.1', 'Strengthen resilience and adaptive capacity to climate-related hazards and natural disasters in all countries', 'Active'), ('SDG_TARGET_13_2', '13.2', 'Integrate climate change measures into national policies, strategies and planning', 'Active'), ('SDG_TARGET_13_3', '13.3', 'Improve education, awareness-raising and human and institutional capacity on climate change mitigation, adaptation, impact reduction and early warning', 'Active'), ('SDG_TARGET_13_a', '13.a', 'Implement the commitment undertaken by developed-country parties to the United Nations Framework Convention on Climate Change to a goal of mobilizing jointly $100 billion annually by 2020 from all sources to address the needs of developing countries in the context of meaningful mitigation actions and transparency on implementation and fully operationalize the Green Climate Fund through its capitalization as soon as possible', 'Active'), ('SDG_TARGET_13_b', '13.b', 'Promote mechanisms for raising capacity for effective climate change-related planning and management in least developed countries and small island developing States, including focusing on women, youth and local and marginalized communities', 'Active'), ('SDG_TARGET_14_1', '14.1', 'By 2025, prevent and significantly reduce marine pollution of all kinds, in particular from land-based activities, including marine debris and nutrient pollution', 'Active'), ('SDG_TARGET_14_2', '14.2', 'By 2020, sustainably manage and protect marine and coastal ecosystems to avoid significant adverse impacts, including by strengthening their resilience, and take action for their restoration in order to achieve healthy and productive oceans', 'Active'), ('SDG_TARGET_14_3', '14.3', 'Minimize and address the impacts of ocean acidification, including through enhanced scientific cooperation at all levels', 'Active'), ('SDG_TARGET_14_4', '14.4', 'By 2020, effectively regulate harvesting and end overfishing, illegal, unreported and unregulated fishing and destructive fishing practices and implement science-based management plans, in order to restore fish stocks in the shortest time feasible, at least to levels that can produce maximum sustainable yield as determined by their biological characteristics', 'Active'), ('SDG_TARGET_14_5', '14.5', 'By 2020, conserve at least 10 per cent of coastal and marine areas, consistent with national and international law and based on the best available scientific information', 'Active'), ('SDG_TARGET_14_6', '14.6', 'By 2020, prohibit certain forms of fisheries subsidies which contribute to overcapacity and overfishing, eliminate subsidies that contribute to illegal, unreported and unregulated fishing and refrain from introducing new such subsidies, recognizing that appropriate and effective special and differential treatment for developing and least developed countries should be an integral part of the World Trade Organization fisheries subsidies negotiation', 'Active'), ('SDG_TARGET_14_7', '14.7', 'By 2030, increase the economic benefits to small island developing States and least developed countries from the sustainable use of marine resources, including through sustainable management of fisheries, aquaculture and tourism', 'Active'), ('SDG_TARGET_14_a', '14.a', 'Increase scientific knowledge, develop research capacity and transfer marine technology, taking into account the Intergovernmental Oceanographic Commission Criteria and Guidelines on the Transfer of Marine Technology, in order to improve ocean health and to enhance the contribution of marine biodiversity to the development of developing countries, in particular small island developing States and least developed countries', 'Active'), ('SDG_TARGET_14_b', '14.b', 'Provide access for small-scale artisanal fishers to marine resources and markets', 'Active'), ('SDG_TARGET_14_c', '14.c', 'Enhance the conservation and sustainable use of oceans and their resources by implementing international law as reflected in the United Nations Convention on the Law of the Sea, which provides the legal framework for the conservation and sustainable use of oceans and their resources, as recalled in paragraph 158 of “The future we want”', 'Active'), ('SDG_TARGET_15_1', '15.1', 'By 2020, ensure the conservation, restoration and sustainable use of terrestrial and inland freshwater ecosystems and their services, in particular forests, wetlands, mountains and drylands, in line with obligations under international agreements', 'Active'), ('SDG_TARGET_15_2', '15.2', 'By 2020, promote the implementation of sustainable management of all types of forests, halt deforestation, restore degraded forests and substantially increase afforestation and reforestation globally', 'Active'), ('SDG_TARGET_15_3', '15.3', 'By 2030, combat desertification, restore degraded land and soil, including land affected by desertification, drought and floods, and strive to achieve a land degradation-neutral world', 'Active'), ('SDG_TARGET_15_4', '15.4', 'By 2030, ensure the conservation of mountain ecosystems, including their biodiversity, in order to enhance their capacity to provide benefits that are essential for sustainable development', 'Active'), ('SDG_TARGET_15_5', '15.5', 'Take urgent and significant action to reduce the degradation of natural habitats, halt the loss of biodiversity and, by 2020, protect and prevent the extinction of threatened species', 'Active'), ('SDG_TARGET_15_6', '15.6', 'Promote fair and equitable sharing of the benefits arising from the utilization of genetic resources and promote appropriate access to such resources, as internationally agreed', 'Active'), ('SDG_TARGET_15_7', '15.7', 'Take urgent action to end poaching and trafficking of protected species of flora and fauna and address both demand and supply of illegal wildlife products', 'Active'), ('SDG_TARGET_15_8', '15.8', 'By 2020, introduce measures to prevent the introduction and significantly reduce the impact of invasive alien species on land and water ecosystems and control or eradicate the priority species', 'Active'), ('SDG_TARGET_15_9', '15.9', 'By 2020, integrate ecosystem and biodiversity values into national and local planning, development processes, poverty reduction strategies and accounts', 'Active'), ('SDG_TARGET_15_a', '15.a', 'Mobilize and significantly increase financial resources from all sources to conserve and sustainably use biodiversity and ecosystems', 'Active'), ('SDG_TARGET_15_b', '15.b', 'Mobilize significant resources from all sources and at all levels to finance sustainable forest management and provide adequate incentives to developing countries to advance such management, including for conservation and reforestation', 'Active'), ('SDG_TARGET_15_c', '15.c', 'Enhance global support for efforts to combat poaching and trafficking of protected species, including by increasing the capacity of local communities to pursue sustainable livelihood opportunities', 'Active'), ('SDG_TARGET_16_1', '16.1', 'Significantly reduce all forms of violence and related death rates everywhere', 'Active'), ('SDG_TARGET_16_10', '16.10', 'Ensure public access to information and protect fundamental freedoms, in accordance with national legislation and international agreements', 'Active'), ('SDG_TARGET_16_2', '16.2', 'End abuse, exploitation, trafficking and all forms of violence against and torture of children', 'Active'), ('SDG_TARGET_16_3', '16.3', 'Promote the rule of law at the national and international levels and ensure equal access to justice for all', 'Active'), ('SDG_TARGET_16_4', '16.4', 'By 2030, significantly reduce illicit financial and arms flows, strengthen the recovery and return of stolen assets and combat all forms of organized crime', 'Active'), ('SDG_TARGET_16_5', '16.5', 'Substantially reduce corruption and bribery in all their forms', 'Active'), ('SDG_TARGET_16_6', '16.6', 'Develop effective, accountable and transparent institutions at all levels', 'Active'), ('SDG_TARGET_16_7', '16.7', 'Ensure responsive, inclusive, participatory and representative decision-making at all levels', 'Active'), ('SDG_TARGET_16_8', '16.8', 'Broaden and strengthen the participation of developing countries in the institutions of global governance', 'Active'), ('SDG_TARGET_16_9', '16.9', 'By 2030, provide legal identity for all, including birth registration', 'Active'), ('SDG_TARGET_16_a', '16.a', 'Strengthen relevant national institutions, including through international cooperation, for building capacity at all levels, in particular in developing countries, to prevent violence and combat terrorism and crime', 'Active'), ('SDG_TARGET_16_b', '16.b', 'Promote and enforce non-discriminatory laws and policies for sustainable development', 'Active') ON CONFLICT DO NOTHING;